// Deterministic synthetic signal, then actual radix-2 FFT and Welch estimation.
const fs=16000,N=4096;let seed=29;function noise(){seed=(1664525*seed+1013904223)>>>0;return seed/4294967296-.5}const signal=Array.from({length:N},(_,n)=>.18*Math.sin(2*Math.PI*1200*n/fs)+.065*Math.sin(2*Math.PI*3200*n/fs)+.025*noise());
function spectrum(samples){const n=samples.length,re=samples.map((x,i)=>x*(.5-.5*Math.cos(2*Math.PI*i/n))),im=Array(n).fill(0);for(let i=1,j=0;i<n;i++){let bit=n>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j)[re[i],re[j]]=[re[j],re[i]]}for(let len=2;len<=n;len*=2){for(let i=0;i<n;i+=len){for(let j=0;j<len/2;j++){const angle=-2*Math.PI*j/len,c=Math.cos(angle),s=Math.sin(angle),k=i+j+len/2,tr=re[k]*c-im[k]*s,ti=re[k]*s+im[k]*c;re[k]=re[i+j]-tr;im[k]=im[i+j]-ti;re[i+j]+=tr;im[i+j]+=ti}}}return re.slice(0,n/2+1).map((r,i)=>r*r+im[i]*im[i])}
const fft=spectrum(signal).map((p,i)=>({x:i*fs/N/1000,y:10*Math.log10(Math.max(1e-12,p*4/(N*N*.25)))}));const segment=1024,psd=Array(segment/2+1).fill(0);let count=0;for(let start=0;start+segment<=N;start+=segment/2){spectrum(signal.slice(start,start+segment)).forEach((p,i)=>psd[i]+=2*p/(fs*segment*.375));count++}const welch=psd.map((p,i)=>({x:i*fs/segment/1000,y:10*Math.log10(Math.max(1e-14,p/count))}));const wave=signal.slice(0,640).map((y,i)=>({x:i/fs*1000,y}));
let mode='fft',pointer=null;const cfg={fft:{data:fft,title:'FFT 幅值频谱',sub:'Hann window · 单边幅值谱',xmin:0,xmax:8,ymin:-100,ymax:0,xt:[0,2,4,6,8],yt:[-100,-80,-60,-40,-20,0],xl:'Frequency (kHz)',yl:'Amplitude (dBFS)'},wave:{data:wave,title:'时域波形',sub:'Time domain · 40 ms',xmin:0,xmax:40,ymin:-.3,ymax:.3,xt:[0,10,20,30,40],yt:[-.3,-.15,0,.15,.3],xl:'Time (ms)',yl:'Amplitude (FS)'},welch:{data:welch,title:'Welch 功率谱密度',sub:'Hann window · 1024 点分段 · 50% 重叠',xmin:0,xmax:8,ymin:-110,ymax:-20,xt:[0,2,4,6,8],yt:[-110,-90,-70,-50,-30],xl:'Frequency (kHz)',yl:'PSD (dBFS²/Hz)'}};
function renderSignal(){const d=cfg[mode],w=Math.max(285,$('#signal-chart').clientWidth-(innerWidth<700?14:50)),h=w<500?270:340,m={l:w<500?54:74,r:22,t:25,b:53},pw=w-m.l-m.r,ph=h-m.t-m.b,x=v=>m.l+(v-d.xmin)/(d.xmax-d.xmin)*pw,y=v=>m.t+(d.ymax-v)/(d.ymax-d.ymin)*ph;let s='';d.xt.forEach(v=>{s+=`<line class="grid" x1="${x(v)}" y1="${m.t}" x2="${x(v)}" y2="${h-m.b}"/><path class="axis" d="M${x(v)},${h-m.b}v-5 M${x(v)},${m.t}v5"/><text x="${x(v)}" y="${h-m.b+20}" text-anchor="middle">${v}</text>`});d.yt.forEach(v=>{s+=`<line class="grid" x1="${m.l}" y1="${y(v)}" x2="${w-m.r}" y2="${y(v)}"/><path class="axis" d="M${m.l},${y(v)}h5 M${w-m.r},${y(v)}h-5"/><text x="${m.l-10}" y="${y(v)+4}" text-anchor="end">${v}</text>`});const path=d.data.map((p,i)=>`${i?'L':'M'}${x(p.x).toFixed(2)},${y(Math.max(d.ymin,Math.min(d.ymax,p.y))).toFixed(2)}`).join(' ');s+=`<rect class="axis" x="${m.l}" y="${m.t}" width="${pw}" height="${ph}"/><path d="${path}" fill="none" stroke="#0072BD" stroke-width="1.1" stroke-linejoin="round"/><text class="axis-label" x="${m.l+pw/2}" y="${h-8}" text-anchor="middle">${d.xl}</text><text class="axis-label" transform="translate(16 ${m.t+ph/2}) rotate(-90)" text-anchor="middle">${d.yl}</text>`;
if(pointer!==null){const p=d.data[Math.min(d.data.length-1,Math.max(0,Math.round(pointer*(d.data.length-1))))],px=x(p.x),py=y(Math.max(d.ymin,p.y)),tw=mode==='wave'?155:170,tx=Math.max(m.l,Math.min(w-m.r-tw,px-60));s+=`<path d="M${px},${m.t}V${h-m.b}" stroke="#a3aab5" stroke-dasharray="3 3"/><circle cx="${px}" cy="${py}" r="3.5" fill="#0072BD" stroke="white"/><rect x="${tx}" y="2" width="${tw}" height="23" rx="4" fill="white" stroke="#dde0e4"/><text x="${tx+8}" y="18" style="font-size:11px">${p.x.toFixed(2)} ${mode==='wave'?'ms':'kHz'} / ${p.y.toFixed(2)} ${mode==='wave'?'FS':'dB'}</text>`}
$('#signal-chart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${d.title}，交互体验。点击或左右移动指针可读取数值。" tabindex="0">${s}</svg>`;const svg=$('#signal-chart svg');function updatePointer(e){const rect=svg.getBoundingClientRect();pointer=Math.max(0,Math.min(1,((e.clientX-rect.left)*w/rect.width-m.l)/pw));renderSignal()}svg.addEventListener('pointermove',e=>{if(e.pointerType==='mouse')updatePointer(e)});svg.addEventListener('click',updatePointer);svg.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();pointer=Math.max(0,Math.min(1,(pointer??.15)+(e.key==='ArrowRight'?.01:-.01)));renderSignal();$('#signal-chart svg').focus()}if(e.key==='Escape'){pointer=null;renderSignal();$('#signal-chart svg').focus()}})}
$$('[data-plot]').forEach(b=>b.addEventListener('click',()=>{setSelected($$('[data-plot]'),b);mode=b.dataset.plot;pointer=null;$('#plot-panel').setAttribute('aria-labelledby',b.id);$('#plot-title').textContent=cfg[mode].title;$('#plot-sub').textContent=cfg[mode].sub;renderSignal()}));$('#reset-chart').addEventListener('click',()=>{pointer=null;renderSignal()});
function renderTiming(){const w=Math.max(285,$('#timing-chart').clientWidth),h=270,m={l:82,r:23,t:30,b:50},pw=w-m.l-m.r,x=v=>m.l+v/300*pw,labels=['热像告警','声音告警','现场问答'],values=[40,235,40];let s='';[0,50,100,150,200,250,300].forEach(v=>{s+=`<line class="grid" x1="${x(v)}" y1="${m.t}" x2="${x(v)}" y2="${h-m.b}"/><path class="axis" d="M${x(v)},${h-m.b}v-5"/><text x="${x(v)}" y="${h-m.b+19}" text-anchor="middle">${v}</text>`});labels.forEach((label,i)=>{let cy=64+i*57;s+=`<text class="cn" x="${m.l-12}" y="${cy+5}" text-anchor="end">${label}</text><rect x="${m.l}" y="${cy-11}" width="${x(values[i])-m.l}" height="22" fill="${i===1?'#6e87a4':'#0072BD'}"/><text x="${x(values[i])+7}" y="${cy+5}" style="font-size:13px">${values[i]}</text>`});s+=`<rect class="axis" x="${m.l}" y="${m.t}" width="${pw}" height="${h-m.b-m.t}"/><path d="M${x(250)},${m.t}V${h-m.b}" stroke="#9b6f51" stroke-width="1" stroke-dasharray="4 3"/><text class="cn" x="${x(250)-5}" y="17" text-anchor="end" style="fill:#906747;font-size:11px">默认容差 250 ms</text><text class="axis-label" x="${m.l+pw/2}" y="${h-6}" text-anchor="middle">Maximum time offset (ms)</text>`;$('#timing-chart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="三次板端联测最大时差：热像告警40毫秒，声音告警235毫秒，现场问答40毫秒；默认容差250毫秒">${s}</svg>`}
renderSignal();renderTiming();let resizeTimer;addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{renderSignal();renderTiming()},120)});
$('.mini-wave').innerHTML=Array.from({length:100},(_,i)=>`<i style="height:${12+Math.pow(Math.sin(i*.73),2)*75*Math.exp(-Math.pow((i-50)/30,2))+Math.pow(Math.cos(i*1.3),2)*25}px"></i>`).join('');
if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});$$('.section-head,.cap-grid,.analysis-board,.analysis-explain,.alignment-grid,.platform-body,.scenario-panel,.center-head').forEach(e=>{e.classList.add('reveal');observer.observe(e)})}
